text:
I fixed a double-charge bug in our checkout worker last week and need to explain it to the team in tomorrow's review. Can you explain what the race was and why the fix closes it?

Before:
```ts
async function chargeOrder(orderId: string) {
  const order = await db.orders.find(orderId);
  if (order.status !== 'pending') return;
  const charge = await payments.charge(order.customerId, order.totalCents);
  await db.orders.update(orderId, { status: 'paid', chargeId: charge.id });
}
```

After:
```ts
async function chargeOrder(orderId: string) {
  const claimed = await db.orders.updateWhere(
    { id: orderId, status: 'pending' },
    { status: 'charging' },
  );
  if (claimed === 0) return;
  const order = await db.orders.find(orderId);
  const charge = await payments.charge(order.customerId, order.totalCents, { idempotencyKey: `order-${orderId}` });
  await db.orders.update(orderId, { status: 'paid', chargeId: charge.id });
}
```

The queue delivers each message at least once, and we run 4 workers. We saw 23 double charges in October.

I'm reviewing this on my phone before standup and only have a few minutes. Get me up to speed on what this change does and what I should check.

```diff
--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,3 +1,17 @@
-export async function getProfile(id: string) {
-  return db.profiles.find(id);
-}
+const cache = new Map<string, { value: Profile; expires: number }>();
+const TTL_MS = 60_000;
+
+export async function getProfile(id: string) {
+  const hit = cache.get(id);
+  if (hit && hit.expires > Date.now()) return hit.value;
+  const value = await db.profiles.find(id);
+  cache.set(id, { value, expires: Date.now() + TTL_MS });
+  return value;
+}
+
+export function invalidateProfile(id: string) {
+  cache.delete(id);
+}
--- a/src/routes/profile.ts
+++ b/src/routes/profile.ts
@@ -8,5 +8,6 @@
 export async function updateProfile(req: Request) {
   const body = await req.json();
   await db.profiles.update(req.params.id, body);
+  invalidateProfile(req.params.id);
   return Response.json({ ok: true });
 }
```

